struct TreeNode {
    int val; TreeNode *left, *right;
    TreeNode(int x): val(x), left(nullptr), right(nullptr) {}
};
void inorder(TreeNode* root, vector<int>& out) {
    if (!root) return;
    inorder(root->left, out);
    out.push_back(root->val);
    inorder(root->right, out);
}

vector<vector<int>> levelOrder(TreeNode* root) {
    vector<vector<int>> res;
    if (!root) return res;
    queue<TreeNode*> q; q.push(root);
    while (!q.empty()) {
        int sz = q.size();
        vector<int> level;
        for (int i = 0; i < sz; i++) {
            TreeNode* n = q.front(); q.pop();
            level.push_back(n->val);
            if (n->left) q.push(n->left);
            if (n->right) q.push(n->right);
        }
        res.push_back(level);
    }
    return res;
}

int diameter(TreeNode* root, int& best) {
    if (!root) return 0;
    int l = diameter(root->left, best);
    int r = diameter(root->right, best);
    best = max(best, l + r);      // path through this node
    return 1 + max(l, r);         // height upward
}

static class TreeNode { int val; TreeNode left, right; TreeNode(int v) { val = v; } }

// Inorder, recursive.
static void inorder(TreeNode r, List<Integer> out) {
    if (r == null) return;
    inorder(r.left, out); out.add(r.val); inorder(r.right, out);
}

// Inorder, iterative — worth knowing; interviewers ask for it.
static List<Integer> inorderIter(TreeNode root) {
    List<Integer> out = new ArrayList<>();
    Deque<TreeNode> st = new ArrayDeque<>();
    TreeNode cur = root;
    while (cur != null || !st.isEmpty()) {
        while (cur != null) { st.push(cur); cur = cur.left; }
        cur = st.pop();
        out.add(cur.val);
        cur = cur.right;
    }
    return out;
}

